-- =========================================================================
-- DATABASE CHUẨN CHO SYNOLOGY NAS (MariaDB 10 / MySQL)
-- Tối ưu hóa: Batch Insert nhẹ, tương thích 100% phpMyAdmin
-- Bao gồm: Danh mục, Chức danh, 852 Hồ sơ nhân sự đầy đủ
-- =========================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";

CREATE DATABASE IF NOT EXISTS `hrm_trunghai` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `hrm_trunghai`;

-- 1. BẢNG CÔNG TY
DROP TABLE IF EXISTS `companies`;
CREATE TABLE `companies` (
  `company_id` varchar(50) NOT NULL,
  `company_name` varchar(255) NOT NULL,
  `tax_code` varchar(50) DEFAULT NULL,
  `address` text DEFAULT NULL,
  `status` varchar(50) DEFAULT 'Hoạt động',
  PRIMARY KEY (`company_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 2. BẢNG PHÒNG BAN
DROP TABLE IF EXISTS `departments`;
CREATE TABLE `departments` (
  `department_id` varchar(50) NOT NULL,
  `department_name` varchar(255) NOT NULL,
  `status` varchar(50) DEFAULT 'Hoạt động',
  PRIMARY KEY (`department_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 3. BẢNG VỊ TRÍ / CHỨC DANH
DROP TABLE IF EXISTS `positions`;
CREATE TABLE `positions` (
  `position_id` varchar(50) NOT NULL,
  `position_name` varchar(255) NOT NULL,
  `department_id` varchar(50) DEFAULT NULL,
  `status` varchar(50) DEFAULT 'Hoạt động',
  PRIMARY KEY (`position_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 4. BẢNG NHÂN VIÊN CHÍNH (852 NHÂN SỰ)
DROP TABLE IF EXISTS `employees`;
CREATE TABLE `employees` (
  `employee_id` varchar(30) NOT NULL,
  `time_attendance_code` varchar(30) DEFAULT NULL,
  `full_name` varchar(255) NOT NULL,
  `gender` varchar(10) DEFAULT NULL,
  `date_of_birth` date DEFAULT NULL,
  `birth_place` varchar(255) DEFAULT NULL,
  `native_place` varchar(255) DEFAULT NULL,
  `ethnicity` varchar(50) DEFAULT NULL,
  `religion` varchar(50) DEFAULT NULL,
  `nationality` varchar(50) DEFAULT 'Việt Nam',
  `marital_status` varchar(50) DEFAULT NULL,
  `children_count` int DEFAULT 0,
  `tax_code` varchar(30) DEFAULT NULL,
  `department_id` varchar(50) DEFAULT NULL,
  `department_name` varchar(255) DEFAULT NULL,
  `position_id` varchar(50) DEFAULT NULL,
  `job_title` varchar(255) DEFAULT NULL,
  `job_rank` varchar(255) DEFAULT NULL,
  `direct_manager_id` varchar(30) DEFAULT NULL,
  `direct_manager_name` varchar(255) DEFAULT NULL,
  `indirect_manager_id` varchar(30) DEFAULT NULL,
  `indirect_manager_name` varchar(255) DEFAULT NULL,
  `work_location` varchar(255) DEFAULT NULL,
  `work_area` varchar(100) DEFAULT NULL,
  `employment_status` varchar(50) DEFAULT 'Đang làm việc',
  `labor_nature` varchar(50) DEFAULT 'Chính thức',
  `start_date` date DEFAULT NULL,
  `end_date` varchar(50) DEFAULT NULL,
  `contract_type` varchar(255) DEFAULT NULL,
  `trial_start_date` date DEFAULT NULL,
  `official_date` date DEFAULT NULL,
  `resignation_date` date DEFAULT NULL,
  `expected_retirement_date` date DEFAULT NULL,
  `seniority_text` varchar(100) DEFAULT NULL,
  `created_at` timestamp DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`employee_id`),
  KEY `idx_dept` (`department_id`),
  KEY `idx_status` (`employment_status`),
  KEY `idx_attendance` (`time_attendance_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 5. BẢNG LIÊN HỆ & ĐỊA CHỈ
DROP TABLE IF EXISTS `employee_contacts`;
CREATE TABLE `employee_contacts` (
  `employee_id` varchar(30) NOT NULL,
  `full_name` varchar(255) DEFAULT NULL,
  `mobile_phone` varchar(30) DEFAULT NULL,
  `home_phone` varchar(30) DEFAULT NULL,
  `work_email` varchar(255) DEFAULT NULL,
  `personal_email` varchar(255) DEFAULT NULL,
  `permanent_address_full` text DEFAULT NULL,
  `current_address_full` text DEFAULT NULL,
  PRIMARY KEY (`employee_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 6. BẢNG GIẤY TỜ TÙY THÂN
DROP TABLE IF EXISTS `employee_identity_docs`;
CREATE TABLE `employee_identity_docs` (
  `employee_id` varchar(30) NOT NULL,
  `full_name` varchar(255) DEFAULT NULL,
  `id_number` varchar(50) DEFAULT NULL,
  `id_issue_date` date DEFAULT NULL,
  `id_issue_place` varchar(255) DEFAULT NULL,
  `id_expiry_date` date DEFAULT NULL,
  `passport_number` varchar(50) DEFAULT NULL,
  `passport_issue_date` date DEFAULT NULL,
  PRIMARY KEY (`employee_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 7. BẢNG LƯƠNG & NGÂN HÀNG
DROP TABLE IF EXISTS `employee_salaries_banks`;
CREATE TABLE `employee_salaries_banks` (
  `employee_id` varchar(30) NOT NULL,
  `full_name` varchar(255) DEFAULT NULL,
  `salary_grade` varchar(50) DEFAULT NULL,
  `base_salary` decimal(15,2) DEFAULT 0,
  `insurance_salary` decimal(15,2) DEFAULT 0,
  `total_salary` decimal(15,2) DEFAULT 0,
  `bank_account_number` varchar(50) DEFAULT NULL,
  `bank_name` varchar(255) DEFAULT NULL,
  `bank_branch` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`employee_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 8. BẢNG BẢO HIỂM XÃ HỘI
DROP TABLE IF EXISTS `employee_insurance_welfare`;
CREATE TABLE `employee_insurance_welfare` (
  `employee_id` varchar(30) NOT NULL,
  `full_name` varchar(255) DEFAULT NULL,
  `has_insurance` varchar(50) DEFAULT 'Không tham gia',
  `social_insurance_book_no` varchar(50) DEFAULT NULL,
  `social_insurance_code` varchar(50) DEFAULT NULL,
  `insurance_join_date` date DEFAULT NULL,
  `hospital_registered` varchar(255) DEFAULT NULL,
  `union_member` varchar(20) DEFAULT 'Không',
  PRIMARY KEY (`employee_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 9. BẢNG HỢP ĐỒNG LAO ĐỘNG
DROP TABLE IF EXISTS `employee_contracts`;
CREATE TABLE `employee_contracts` (
  `contract_id` varchar(50) NOT NULL,
  `employee_id` varchar(30) NOT NULL,
  `full_name` varchar(255) DEFAULT NULL,
  `contract_type` varchar(255) DEFAULT NULL,
  `trial_start_date` date DEFAULT NULL,
  `official_date` date DEFAULT NULL,
  `contract_status` varchar(50) DEFAULT 'HIỆU LỰC',
  PRIMARY KEY (`contract_id`),
  KEY `idx_contract_emp` (`employee_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 10. BẢNG TÀI KHOẢN ĐĂNG NHẬP
DROP TABLE IF EXISTS `system_accounts`;
CREATE TABLE `system_accounts` (
  `account_id` varchar(50) NOT NULL,
  `employee_id` varchar(30) DEFAULT NULL,
  `username` varchar(100) NOT NULL,
  `full_name` varchar(255) DEFAULT NULL,
  `account_email` varchar(255) DEFAULT NULL,
  `role` varchar(50) DEFAULT 'EMPLOYEE',
  `account_status` varchar(50) DEFAULT 'Kích hoạt',
  `password` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`account_id`),
  UNIQUE KEY `uniq_username` (`username`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =========================================================================
